"use client";

import { Link, RichTextEditor } from "@/components/editor";
import {
  ImagePlaceholder,
  ResizableImage,
} from "@/components/extensions/image-placeholder";
import { Table } from "@/components/extensions/table";
import { TableHoverOverlay } from "@/components/extensions/table/table-hover-overlay";
import { Color } from "@tiptap/extension-color";
import { FontFamily } from "@tiptap/extension-font-family";
import { Highlight } from "@tiptap/extension-highlight";
import { Placeholder } from "@tiptap/extension-placeholder";
import { Subscript } from "@tiptap/extension-subscript";
import { Superscript } from "@tiptap/extension-superscript";
import { TaskItem } from "@tiptap/extension-task-item";
import { TaskList } from "@tiptap/extension-task-list";
import { TextAlign } from "@tiptap/extension-text-align";
import { TextStyle } from "@tiptap/extension-text-style";
import { useEditor, useEditorState } from "@tiptap/react";
import { StarterKit } from "@tiptap/starter-kit";
import { ChevronRight, FileText } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import {
  CANVAS,
  SAMPLE_COLLABORATORS,
  SAMPLE_CONTENT,
  SCROLLBAR,
} from "./constants";
import { Collaborators, MoreMenu } from "./header";
import { ShortcutsPopover } from "./shortcuts";
import { Toolbar } from "./toolbar";
import type { SimpleDocumentEditorProps } from "./types";
import { readState } from "./utils";

import "@/components/editor/style.css";
import "@/components/extensions/image-placeholder/style.css";
import "@/components/extensions/table/style.css";
import "@/components/extensions/ui/style.css";

export const SimpleDocumentEditor = ({
  className,
  collaborators = SAMPLE_COLLABORATORS,
  initialContent = SAMPLE_CONTENT,
  initialTitle = "Onboarding redesign",
  onChange,
  onShare,
  onTitleChange,
  path = ["Product", "Specs"],
}: SimpleDocumentEditorProps) => {
  const [title, setTitle] = useState(initialTitle);

  const editor = useEditor({
    content: initialContent,
    extensions: [
      StarterKit.configure({
        gapcursor: false,
        heading: { levels: [1, 2, 3] },
        link: false,
      }),
      Link,
      TextStyle,
      Color,
      FontFamily,
      Highlight.configure({ multicolor: true }),
      Subscript,
      Superscript,
      Table.configure({ resizable: true }),
      ResizableImage,
      ImagePlaceholder,
      TaskList.configure({ HTMLAttributes: { class: "rte-task-list" } }),
      TaskItem.configure({ nested: true }),
      TextAlign.configure({ types: ["heading", "paragraph"] }),
      Placeholder.configure({ placeholder: "Start writing…" }),
    ],
    immediatelyRender: false,
    onUpdate: ({ editor: updated }) => onChange?.(updated.getJSON()),
    shouldRerenderOnTransaction: false,
  });

  const state =
    useEditorState({
      editor,
      selector: ({ editor: e }) => (e && !e.isDestroyed ? readState(e) : null),
    }) ?? (editor ? readState(editor) : null);

  const words = state?.words ?? 0;

  return (
    <div
      className={cn(
        "bg-background text-foreground flex max-h-[41rem] flex-col overflow-hidden rounded-xl border shadow-sm",
        className
      )}
    >
      <header className="flex h-12 shrink-0 items-center gap-2 border-b px-3">
        <FileText className="text-muted-foreground size-4 shrink-0" />
        <nav
          aria-label="Breadcrumb"
          className="text-muted-foreground flex min-w-0 items-center gap-1 text-sm"
        >
          {path.map((segment) => (
            <span key={segment} className="hidden items-center gap-1 sm:flex">
              {segment}
              <ChevronRight className="size-3.5 opacity-50" />
            </span>
          ))}
          <span className="text-foreground truncate font-medium">
            {title || "Untitled"}
          </span>
        </nav>
        <div className="ml-auto flex items-center gap-2">
          <div className="hidden sm:block">
            <Collaborators people={collaborators} />
          </div>
          {onShare && (
            <Button
              className="h-7 rounded-md px-3 text-xs"
              onClick={onShare}
              size="sm"
            >
              Share
            </Button>
          )}
          <MoreMenu editor={editor} />
        </div>
      </header>

      <RichTextEditor
        editor={editor}
        variant="subtle"
        className={cn(
          "min-h-0 flex-1 overflow-y-auto rounded-none! border-0! shadow-none!",
          CANVAS,
          SCROLLBAR
        )}
      >
        <Toolbar editor={editor} state={state} />
        <article className="bg-background mx-3 mt-4 mb-6 rounded-lg border px-5 py-6 shadow-xs sm:mx-auto sm:max-w-3xl sm:px-14 sm:py-12">
          <input
            aria-label="Document title"
            className="placeholder:text-muted-foreground/60 mb-4 w-full bg-transparent text-2xl font-bold tracking-tight outline-none sm:text-3xl"
            onChange={(e) => {
              setTitle(e.target.value);
              onTitleChange?.(e.target.value);
            }}
            placeholder="Untitled"
            value={title}
          />
          <RichTextEditor.Content className="[&_.ProseMirror]:min-h-64! [&_.ProseMirror]:p-0! [&_mark]:rounded-sm [&_mark]:px-0.5 [&_mark]:text-inherit [&_mark:not([style])]:bg-yellow-400/40" />
        </article>
      </RichTextEditor>
      <TableHoverOverlay editor={editor} />

      <footer className="text-muted-foreground flex h-9 shrink-0 items-center gap-3 border-t px-3 text-xs tabular-nums">
        <span>{words.toLocaleString()} words</span>
        <span>{(state?.characters ?? 0).toLocaleString()} characters</span>
        <span className="hidden sm:inline">
          {Math.max(1, Math.ceil(words / 200))} min read
        </span>
        <div className="ml-auto">
          <ShortcutsPopover />
        </div>
      </footer>
    </div>
  );
};

export type { DocumentCollaborator, SimpleDocumentEditorProps } from "./types";

import { AlignCenter, AlignJustify, AlignLeft, AlignRight } from "lucide-react";

import type { DocumentCollaborator } from "./types";

export const SAMPLE_CONTENT = `
<p>We're rebuilding the first-run experience so new teams reach their first shared document in under <mark>two minutes</mark>. This page tracks scope, decisions and open questions.</p>
<h2>Goals</h2>
<ul>
  <li><p>Cut the setup flow from seven steps to three</p></li>
  <li><p>Invite teammates before the first document is created</p></li>
  <li><p>Replace the empty state with three starter templates</p></li>
</ul>
<h2>Milestones</h2>
<ul data-type="taskList">
  <li data-type="taskItem" data-checked="true"><p>Interview twelve teams who churned in week one</p></li>
  <li data-type="taskItem" data-checked="true"><p>Prototype the three-step flow</p></li>
  <li data-type="taskItem" data-checked="false"><p>Usability test with <strong>five</strong> new teams</p></li>
  <li data-type="taskItem" data-checked="false"><p>Ship behind the <code>onboarding-v2</code> flag</p></li>
</ul>
<blockquote><p>"I didn't know what to write first, so I closed the tab."</p></blockquote>
<h2>Open questions</h2>
<p>Should templates be picked by role or by use case? Research leans towards use case, but sales wants role-based starters for enterprise trials.</p>
`;

export const SAMPLE_COLLABORATORS: DocumentCollaborator[] = [
  { name: "Ava Thompson" },
  { name: "Noah Kim" },
  { name: "Lena Novak" },
];

export const TEXT_STYLES = [
  { className: "", label: "Paragraph", value: "0" },
  { className: "font-bold", label: "Heading 1", value: "1" },
  { className: "font-semibold", label: "Heading 2", value: "2" },
  { className: "font-medium", label: "Heading 3", value: "3" },
] as const;

export const ALIGNMENTS = [
  { Icon: AlignLeft, label: "Left", value: "left" },
  { Icon: AlignCenter, label: "Center", value: "center" },
  { Icon: AlignRight, label: "Right", value: "right" },
  { Icon: AlignJustify, label: "Justify", value: "justify" },
] as const;

export const FONTS = [
  { label: "Sans", value: "" },
  { label: "Serif", value: "ui-serif, Georgia, serif" },
  { label: "Mono", value: "ui-monospace, SFMono-Regular, Menlo, monospace" },
] as const;

export const TEXT_COLORS = [
  { label: "Gray", value: "#6b7280" },
  { label: "Red", value: "#dc2626" },
  { label: "Orange", value: "#ea580c" },
  { label: "Green", value: "#16a34a" },
  { label: "Blue", value: "#2563eb" },
  { label: "Purple", value: "#9333ea" },
];

export const HIGHLIGHTS = [
  { label: "Yellow highlight", value: "rgb(250 204 21 / 0.4)" },
  { label: "Green highlight", value: "rgb(74 222 128 / 0.35)" },
  { label: "Blue highlight", value: "rgb(96 165 250 / 0.35)" },
  { label: "Pink highlight", value: "rgb(244 114 182 / 0.35)" },
  { label: "Purple highlight", value: "rgb(192 132 252 / 0.35)" },
];

export const SHORTCUTS = [
  {
    items: [
      ["Bold", "Mod+B"],
      ["Italic", "Mod+I"],
      ["Underline", "Mod+U"],
      ["Strikethrough", "Mod+Shift+S"],
      ["Inline code", "Mod+E"],
      ["Highlight", "Mod+Shift+H"],
      ["Superscript", "Mod+."],
      ["Subscript", "Mod+,"],
      ["Link", "Mod+K"],
      ["Heading 1 to 3", "Mod+Alt+1"],
      ["Task list", "Mod+Shift+9"],
      ["Indent", "Tab"],
    ],
    title: "Formatting",
  },
  {
    items: [
      ["Heading", "#"],
      ["Bullet list", "-"],
      ["Numbered list", "1."],
      ["Task list", "[ ]"],
      ["Quote", ">"],
      ["Code block", "```"],
      ["Divider", "---"],
    ],
    title: "Markdown",
  },
] as const;

export const SCROLLBAR =
  "[scrollbar-color:var(--border)_transparent] [scrollbar-width:thin] [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-border [&::-webkit-scrollbar-track]:bg-transparent";

export const CANVAS =
  "bg-[color-mix(in_oklab,var(--muted)_50%,var(--background))]!";

export const SCROLL_SHADOWS = {
  background: [
    "linear-gradient(to right, var(--background) 30%, transparent) left / 2.5rem 100% no-repeat local",
    "linear-gradient(to left, var(--background) 30%, transparent) right / 2.5rem 100% no-repeat local",
    "radial-gradient(farthest-side at 0 50%, rgb(0 0 0 / 0.14), transparent) left / 0.75rem 100% no-repeat scroll",
    "radial-gradient(farthest-side at 100% 50%, rgb(0 0 0 / 0.14), transparent) right / 0.75rem 100% no-repeat scroll",
    "var(--background)",
  ].join(", "),
};

export const ACTIVE_ITEM =
  "rounded-md py-1 pl-2 text-[13px] data-[state=checked]:bg-accent data-[state=checked]:text-accent-foreground data-checked:bg-accent data-checked:text-accent-foreground [&>span:first-child]:hidden [&_svg:not([class*='size-'])]:size-3.5";

"use client";

import type { Editor } from "@tiptap/react";
import { Copy, MoreHorizontal, Printer } from "lucide-react";

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

import type { DocumentCollaborator } from "./types";
import { initials } from "./utils";

export const Collaborators = ({
  people,
}: {
  people: DocumentCollaborator[];
}) => (
  <div className="flex -space-x-1.5">
    {people.map((person) => (
      <Tooltip key={person.name}>
        <TooltipTrigger asChild>
          <Avatar className="ring-background size-6 ring-2">
            {person.src && <AvatarImage alt={person.name} src={person.src} />}
            <AvatarFallback className="text-[0.6rem] font-medium">
              {initials(person.name)}
            </AvatarFallback>
          </Avatar>
        </TooltipTrigger>
        <TooltipContent>{person.name}</TooltipContent>
      </Tooltip>
    ))}
  </div>
);

export const MoreMenu = ({ editor }: { editor: Editor | null }) => (
  <DropdownMenu>
    <DropdownMenuTrigger asChild>
      <Button
        aria-label="More options"
        className="text-muted-foreground size-7"
        size="icon-sm"
        variant="ghost"
      >
        <MoreHorizontal />
      </Button>
    </DropdownMenuTrigger>
    <DropdownMenuContent align="end" className="min-w-36 p-1">
      <DropdownMenuItem
        className="rounded-md py-1 text-[13px] [&_svg]:size-3.5!"
        onClick={() => navigator.clipboard.writeText(editor?.getHTML() ?? "")}
      >
        <Copy />
        Copy as HTML
      </DropdownMenuItem>
      <DropdownMenuItem
        className="rounded-md py-1 text-[13px] [&_svg]:size-3.5!"
        onClick={() => window.print()}
      >
        <Printer />
        Print
      </DropdownMenuItem>
    </DropdownMenuContent>
  </DropdownMenu>
);

"use client";

import { Keyboard } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Kbd, KbdGroup } from "@/components/ui/kbd";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

import { SCROLLBAR, SHORTCUTS } from "./constants";

export const ShortcutsPopover = () => {
  const mod = /Mac|iPhone|iPad/.test(globalThis.navigator?.userAgent ?? "")
    ? "⌘"
    : "Ctrl";
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          className="text-muted-foreground h-6 gap-1.5 px-2 text-xs"
          size="sm"
          variant="ghost"
        >
          <Keyboard className="size-3.5" />
          Shortcuts
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="end"
        className={cn("max-h-80 w-72 overflow-y-auto p-3", SCROLLBAR)}
        side="top"
      >
        <p className="mb-2 text-sm font-medium">Keyboard shortcuts</p>
        {SHORTCUTS.map((section) => (
          <div key={section.title} className="mb-3 last:mb-0">
            <p className="text-muted-foreground mb-1 text-xs">
              {section.title}
            </p>
            {section.items.map(([label, keys]) => (
              <div
                key={label}
                className="flex items-center justify-between py-1 text-sm"
              >
                {label}
                <KbdGroup>
                  {keys.split("+").map((key) => (
                    <Kbd key={key}>{key === "Mod" ? mod : key}</Kbd>
                  ))}
                </KbdGroup>
              </div>
            ))}
          </div>
        ))}
      </PopoverContent>
    </Popover>
  );
};

"use client";

import { RichTextEditor } from "@/components/editor";
import type { Editor } from "@tiptap/react";
import {
  AlignLeft,
  Ban,
  Baseline,
  ChevronDown,
  Code2,
  Image as ImageIcon,
  IndentDecrease,
  IndentIncrease,
  ListTodo,
  Minus,
  Plus,
  Quote,
  Table as TableIcon,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";

import {
  ACTIVE_ITEM,
  ALIGNMENTS,
  CANVAS,
  FONTS,
  HIGHLIGHTS,
  SCROLL_SHADOWS,
  TEXT_COLORS,
  TEXT_STYLES,
} from "./constants";
import type { EditorSnapshot } from "./utils";

const TextStyleMenu = ({
  editor,
  value,
}: {
  editor: Editor | null;
  value: string;
}) => (
  <DropdownMenu>
    <DropdownMenuTrigger asChild>
      <Button
        className="h-8 w-[6.5rem] justify-between px-2 text-[13px]"
        size="sm"
        variant="ghost"
      >
        {TEXT_STYLES.find((s) => s.value === value)?.label}
        <ChevronDown className="text-muted-foreground size-3.5" />
      </Button>
    </DropdownMenuTrigger>
    <DropdownMenuContent align="start" className="min-w-32 p-1">
      <DropdownMenuRadioGroup
        className="flex flex-col gap-0.5"
        value={value}
        onValueChange={(next) => {
          const level = Number(next) as 0 | 1 | 2 | 3;
          const chain = editor?.chain().focus();
          (level ? chain?.setHeading({ level }) : chain?.setParagraph())?.run();
        }}
      >
        {TEXT_STYLES.map((style) => (
          <DropdownMenuRadioItem
            key={style.value}
            className={cn(ACTIVE_ITEM, style.className)}
            value={style.value}
          >
            {style.label}
          </DropdownMenuRadioItem>
        ))}
      </DropdownMenuRadioGroup>
    </DropdownMenuContent>
  </DropdownMenu>
);

const AlignMenu = ({
  editor,
  value,
}: {
  editor: Editor | null;
  value: string;
}) => {
  const Icon = ALIGNMENTS.find((a) => a.value === value)?.Icon ?? AlignLeft;
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          aria-label="Text alignment"
          className="text-muted-foreground h-8 gap-0.5 px-1.5"
          size="sm"
          variant="ghost"
        >
          <Icon />
          <ChevronDown className="size-3!" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-28 p-1">
        <DropdownMenuRadioGroup
          className="flex flex-col gap-0.5"
          value={value}
          onValueChange={(next) =>
            editor?.chain().focus().setTextAlign(next).run()
          }
        >
          {ALIGNMENTS.map(({ Icon: ItemIcon, label, value: v }) => (
            <DropdownMenuRadioItem key={v} className={ACTIVE_ITEM} value={v}>
              <ItemIcon />
              {label}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

const FontMenu = ({
  editor,
  value,
}: {
  editor: Editor | null;
  value: string;
}) => (
  <DropdownMenu>
    <DropdownMenuTrigger asChild>
      <Button
        aria-label="Font"
        className="h-8 w-[4.5rem] justify-between px-2 text-[13px]"
        size="sm"
        variant="ghost"
      >
        <span style={{ fontFamily: value || undefined }}>
          {FONTS.find((f) => f.value === value)?.label ?? "Sans"}
        </span>
        <ChevronDown className="text-muted-foreground size-3.5" />
      </Button>
    </DropdownMenuTrigger>
    <DropdownMenuContent align="start" className="min-w-28 p-1">
      <DropdownMenuRadioGroup
        className="flex flex-col gap-0.5"
        value={value}
        onValueChange={(next) => {
          const chain = editor?.chain().focus();
          (next ? chain?.setFontFamily(next) : chain?.unsetFontFamily())?.run();
        }}
      >
        {FONTS.map((font) => (
          <DropdownMenuRadioItem
            key={font.label}
            className={ACTIVE_ITEM}
            style={{ fontFamily: font.value || undefined }}
            value={font.value}
          >
            {font.label}
          </DropdownMenuRadioItem>
        ))}
      </DropdownMenuRadioGroup>
    </DropdownMenuContent>
  </DropdownMenu>
);

const Swatch = ({
  active,
  color,
  label,
  onClick,
}: {
  active: boolean;
  color?: string;
  label: string;
  onClick: () => void;
}) => (
  <button
    aria-label={label}
    aria-pressed={active}
    className={cn(
      "relative flex size-6 items-center justify-center rounded-full border transition-transform active:scale-96",
      active && "ring-ring ring-2 ring-offset-1 ring-offset-background"
    )}
    onClick={onClick}
    style={{ background: color }}
    title={label}
    type="button"
  >
    {!color && <Ban className="text-muted-foreground size-3.5" />}
  </button>
);

const ColorMenu = ({
  editor,
  highlight,
  text,
}: {
  editor: Editor | null;
  highlight?: string;
  text?: string;
}) => (
  <Popover>
    <PopoverTrigger asChild>
      <Button
        aria-label="Text color"
        className="h-8 flex-col gap-0 px-1.5"
        size="sm"
        variant="ghost"
      >
        <Baseline className="size-4" />
        <span
          className="-mt-0.5 h-1 w-4 rounded-full"
          style={{ background: highlight ?? text ?? "currentColor" }}
        />
      </Button>
    </PopoverTrigger>
    <PopoverContent align="start" className="w-auto space-y-3 p-3">
      <div>
        <p className="text-muted-foreground mb-2 text-xs">Text</p>
        <div className="flex gap-1.5">
          <Swatch
            active={!text}
            label="Default text color"
            onClick={() => editor?.chain().focus().unsetColor().run()}
          />
          {TEXT_COLORS.map(({ label, value }) => (
            <Swatch
              key={value}
              active={text === value}
              color={value}
              label={label}
              onClick={() => editor?.chain().focus().setColor(value).run()}
            />
          ))}
        </div>
      </div>
      <div>
        <p className="text-muted-foreground mb-2 text-xs">Highlight</p>
        <div className="flex gap-1.5">
          <Swatch
            active={!highlight}
            label="No highlight"
            onClick={() => editor?.chain().focus().unsetHighlight().run()}
          />
          {HIGHLIGHTS.map(({ label, value }) => (
            <Swatch
              key={value}
              active={highlight === value}
              color={value}
              label={label}
              onClick={() =>
                editor?.chain().focus().setHighlight({ color: value }).run()
              }
            />
          ))}
        </div>
      </div>
    </PopoverContent>
  </Popover>
);

const InsertMenu = ({ editor }: { editor: Editor | null }) => {
  const run = (command: (chain: ReturnType<Editor["chain"]>) => void) => {
    if (editor) {
      command(editor.chain().focus());
    }
  };
  const items = [
    {
      Icon: ImageIcon,
      label: "Image",
      onSelect: () => run((c) => c.insertImagePlaceholder().run()),
    },
    {
      Icon: TableIcon,
      label: "Table",
      onSelect: () =>
        run((c) =>
          c.insertTable({ cols: 3, rows: 3, withHeaderRow: true }).run()
        ),
    },
    {
      Icon: Quote,
      label: "Quote",
      onSelect: () => run((c) => c.toggleBlockquote().run()),
    },
    {
      Icon: Code2,
      label: "Code block",
      onSelect: () => run((c) => c.toggleCodeBlock().run()),
    },
    {
      Icon: Minus,
      label: "Divider",
      onSelect: () => run((c) => c.setHorizontalRule().run()),
    },
  ];
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          className="h-8 gap-1 px-2 text-[13px]"
          size="sm"
          variant="ghost"
        >
          <Plus className="size-4" />
          Insert
          <ChevronDown className="text-muted-foreground size-3.5" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-36 p-1">
        {items.map(({ Icon, label, onSelect }) => (
          <DropdownMenuItem
            key={label}
            className="rounded-md py-1 text-[13px] [&_svg]:size-3.5!"
            onClick={onSelect}
          >
            <Icon />
            {label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

const ListControls = ({
  editor,
  state,
}: {
  editor: Editor | null;
  state: EditorSnapshot | null;
}) => {
  const listCommand = (command: "liftListItem" | "sinkListItem") => {
    const chain = editor?.chain().focus();
    (editor?.can()[command]("listItem")
      ? chain?.[command]("listItem")
      : chain?.[command]("taskItem")
    )?.run();
  };
  return (
    <RichTextEditor.ControlsGroup>
      <RichTextEditor.BulletList />
      <RichTextEditor.OrderedList />
      <RichTextEditor.Control
        active={state?.taskList}
        aria-label="Task list"
        title="Task list"
        onClick={() => editor?.chain().focus().toggleTaskList().run()}
      >
        <ListTodo className="size-4" />
      </RichTextEditor.Control>
      <RichTextEditor.Control
        aria-label="Outdent"
        disabled={!state?.canOutdent}
        title="Outdent"
        onClick={() => listCommand("liftListItem")}
      >
        <IndentDecrease className="size-4" />
      </RichTextEditor.Control>
      <RichTextEditor.Control
        aria-label="Indent"
        disabled={!state?.canIndent}
        title="Indent"
        onClick={() => listCommand("sinkListItem")}
      >
        <IndentIncrease className="size-4" />
      </RichTextEditor.Control>
      <AlignMenu editor={editor} value={state?.align ?? "left"} />
    </RichTextEditor.ControlsGroup>
  );
};

export const Toolbar = ({
  editor,
  state,
}: {
  editor: Editor | null;
